import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source
cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int BLOCK_SIZE>
__global__ void matvec_fp16_kernel(const __half* __restrict__ A,
                                   const __half* __restrict__ B,
                                   __half* __restrict__ C,
                                   int M,
                                   int K) {
    // each block handles one output row
    int row = blockIdx.x;
    if (row >= M) return;

    int tid = threadIdx.x;
    float sum = 0.0f;

    // stride over K dimension
    for (int col = tid; col < K; col += BLOCK_SIZE) {
        __half a = A[row * K + col];
        __half b = B[col];
        sum += __half2float(a) * __half2float(b);
    }

    // reduction in shared memory
    __shared__ float shmem[BLOCK_SIZE];
    shmem[tid] = sum;
    __syncthreads();

    // tree reduction
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shmem[tid] += shmem[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        C[row] = __float2half(shmem[0]);
    }
}

// launch helper
void launch_matvec_fp16(const torch::Tensor& A,
                        const torch::Tensor& B,
                        torch::Tensor& C) {
    const int M = A.size(0);
    const int K = A.size(1);
    const int BLOCK_SIZE = 256; // fits A100 well

    const dim3 grid(M);
    const dim3 block(BLOCK_SIZE);
    const auto stream = at::cuda::getCurrentCUDAStream();

    AT_DISPATCH_HALF_TYPES(A.scalar_type(), "matvec_fp16_launcher", [&] {
        matvec_fp16_kernel<BLOCK_SIZE><<<grid, block, 0, stream>>>(
            reinterpret_cast<const __half*>(A.data_ptr<scalar_t>()),
            reinterpret_cast<const __half*>(B.data_ptr<scalar_t>()),
            reinterpret_cast<__half*>(C.data_ptr<scalar_t>()),
            M,
            K
        );
    });

    // optional error check (helps debugging)
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }
}
'''

# Build the extension in‑line
matvec_ext = load_inline(name='matvec_ext',
                         cpp_sources='',
                         cuda_sources=cuda_src,
                         functions=['launch_matvec_fp16'],
                         verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Performs C = A @ B where A ∈ (M, K), B ∈ (K, 1), all half‑precision.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Ensure inputs are half and contiguous on CUDA
        if not A.is_cuda or not B.is_cuda:
            raise RuntimeError("ModelNew only supports CUDA tensors")
        A = A.to(dtype=torch.float16, memory_format=torch.contiguous_format)
        B = B.to(dtype=torch.float16, memory_format=torch.contiguous_format)

        if A.dim() != 2 or B.dim() != 2:
            raise RuntimeError("Expected A shape (M, K) and B shape (K, 1)")

        M, K = A.shape
        if B.shape != (K, 1):
            raise RuntimeError(f"Incompatible shapes: A {A.shape}, B {B.shape}")

        # Allocate output
        C = torch.empty((M, 1), dtype=torch.float16, device=A.device)

        # Call the CUDA kernel
        matvec_ext.launch_matvec_fp16(A, B.squeeze(-1), C)

        return C

# Example usage (mirrors the reference's get_inputs)
if __name__ == "__main__":
    M = 256 * 8          # 2048
    K = 131072 * 8       # 1048576
    A = torch.rand(M, K, dtype=torch.float16, device='cuda')
    B = torch.rand(K, 1, dtype=torch.float16, device='cuda')
    model = ModelNew().cuda()
    C = model(A, B)
    # Verify against torch.matmul (cast to fp16 for fair compare)
    C_ref = torch.matmul(A, B)
    print("Max absolute error:", (C - C_ref).abs().max().item())
